import { useEffect, useState } from "react";

function FacultyList() {
  const [selectedFaculty, setSelectedFaculty] = useState(null);
  const [rating, setRating] = useState("");
  const [comment, setComment] = useState("");
  const [faculties, setFaculties] = useState([]);
  const [facultyFeedback, setFacultyFeedback] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchFaculties();
  }, []);

  const fetchFaculties = async () => {
    try {
      const token = localStorage.getItem("token");

      const response = await fetch("http://localhost:5001/faculties", {
        method: "GET",
        headers: {
          Authorization: "Bearer " + token,
        },
      });

      const data = await response.json();
      setFaculties(data);
    } catch (error) {
      console.error("Error:", error);
    }
  };

  const handleSubmit = async () => {
    try {
      const token = localStorage.getItem("token");

      const response = await fetch("http://localhost:5001/feedback", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + token,
        },
        body: JSON.stringify({
          faculty_id: selectedFaculty.id,
          rating: rating,
          comment: comment,
        }),
      });

      const data = await response.json();

      if (response.ok) {
        alert("Feedback Submitted..");


        setRating("");
        setComment("");
        setSelectedFaculty(null);

      } else {
        alert(data.message);
      }
    } catch (error) {
      console.error(error);
    }
  };

  const fetchFeedback = async (facultyId) => {
    try {
      setLoading(true);
      const token = localStorage.getItem("token");

      const response = await fetch(
        `http://localhost:5001/faculties/${facultyId}/feedback`,
        {
          method: "GET",
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      );

      const data = await response.json();

      if (response.ok) {
        setFacultyFeedback(data);
      } else {
        alert(data.message);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h2>Faculty List</h2>

      {faculties.map((faculty) => (
        <div key={faculty.id}>
          <p>
            <b>{faculty.name}</b> - {faculty.department}
          </p>

          <button
            onClick={() => {
              setSelectedFaculty(faculty);
              setFacultyFeedback(null); 
            }}
          >
            Give Feedback
          </button>

          <button onClick={() => fetchFeedback(faculty.id)}>
            View Feedback
          </button>
        </div>
      ))}

      {selectedFaculty && (
        <div>
          <h3>Feedback for {selectedFaculty.name}</h3>

          <input
            type="number"
            placeholder="rating (1-5)"
            value={rating}
            onChange={(e) => setRating(e.target.value)}
          />

          <br />
          <br />

          <input
            type="text"
            placeholder="comment"
            value={comment}
            onChange={(e) => setComment(e.target.value)}
          />

          <br />
          <br />

          <button onClick={handleSubmit}>Submit Feedback</button>
        </div>
      )}

      {loading && <p>Loading feedback...</p>}

      {facultyFeedback && (
        <div>
          <h3>Feedback for {facultyFeedback.faculty.name}</h3>
          <p>
            <b>Department:</b> {facultyFeedback.faculty.department}
          </p>
          <p>
            <b>Average Rating:</b> {facultyFeedback.averageFeedback}
          </p>
          <p>
            <b>Total Feedback:</b> {facultyFeedback.totalFeedback}
          </p>

          <h4>Comments:</h4>

          {facultyFeedback.feedback.length > 0 ? (
            facultyFeedback.feedback.map((item, index) => (
              <div key={index}>
                <p> {item.rating} ⭐</p>
                <p>{item.comment}</p>
                <hr />
              </div>
            ))
          ) : (
            <p>No feedback available yet.</p>
          )}
        </div>
      )}
    </div>
  );
}

export default FacultyList;
